# Insert sector planner method before rebalanceSuggestions
marker=' rebalanceSuggestions(){'
assert marker in s
method=''' sectorRebalancePlanner(){const assets=(this.state.assets||[]).filter(a=>Number(a.value||0)>0),sectors=[...new Set(assets.map(a=>String(a.sector||'').trim()||'Unspecified sector'))].sort((a,b)=>a.localeCompare(b));const targets=this.state.settings?.sectorTargets||{};const total=assets.reduce((n,a)=>n+Number(a.value||0),0);const targetTotal=sectors.reduce((n,k)=>n+Number(targets[k]||0),0);const form=sectors.length?`<div class="formgrid rebalance-targets">${sectors.map((sector,i)=>`<div class="field"><label>${this.esc(sector)} target %</label><input type="number" min="0" max="100" step="0.1" data-sector-target="${i}" data-sector-name="${this.esc(sector)}" value="${Number(targets[sector]||0)}"></div>`).join('')}</div><div class="actions"><button class="btn primary" data-action="save-sector-targets">Update sector ideas</button></div><p class="help">Targets are compared against assets with a recorded sector. Holdings without a sector are grouped as “Unspecified sector”. Target percentages should total 100% for a complete plan.</p>`:'<div class="empty">Add assets and enter their Sector field to use sector-level planning.</div>';const ideas=sectors.filter(k=>Number(targets[k])>0).map(sector=>{const val=assets.filter(a=>(String(a.sector||'').trim()||'Unspecified sector')===sector).reduce((n,a)=>n+Number(a.value||0),0),pct=total?val/total*100:0,target=Number(targets[sector]),diff=target-pct,amount=total*target/100-val,close=Math.abs(diff)<1;return `<div class="rebalance-idea-row"><div class="rebalance-idea-copy"><b>${this.esc(sector)}</b><small>Current ${this.money(val)} · Actual ${pct.toFixed(1)}% · Target ${target.toFixed(1)}% · Difference ${diff>0?'+':''}${diff.toFixed(1)}%</small></div><div class="rebalance-idea-action ${close?'rb-neutral':diff>0?'rb-more':'rb-less'}">${close?'Near target':diff>0?`Invest more · ${this.money(Math.max(0,amount))}`:`Over target · redirect about ${this.money(Math.abs(amount))}`}<small>${diff>0?`Suggested additional amount: ${this.money(amount)}`:diff<0?`Amount to redirect: ${this.money(Math.abs(amount))}`:'No material change suggested'}</small></div></div>`}).join('');return `<details class="panel rebalance-idea-dropdown" data-persist-key="rebalance-sector-planner"${this.disclosureAttr('rebalance-sector-planner')}><summary><b>Target allocation planner by Sector</b><span class="note">Set target percentages for each recorded sector</span></summary><div class="rebalance-idea-content">${form}<p class="note">Entered sector target total: ${targetTotal.toFixed(1)}%. Current sector-assigned asset value: ${this.money(total)}.</p><details class="panel rebalance-idea-dropdown" data-persist-key="rebalance-sector-ideas"${this.disclosureAttr('rebalance-sector-ideas')}><summary><b>Sector-wise rebalancing ideas</b><span class="note">More / less guidance by sector</span></summary><div class="rebalance-idea-list">${ideas||'<div class="empty">Enter target percentages above to see sector-wise rebalancing ideas.</div>'}</div></details></div></details>`},
'''
