# Add file export/import methods before syncPayload
marker=' async syncPayload(){'
methods=''' async exportVaultFile(){let picker=null;try{if(window.showSaveFilePicker)picker=window.showSaveFilePicker({suggestedName:'FinMate-vault.json',types:[{description:'FinMate encrypted vault',accept:{'application/json':['.json']}}]});await this.persist(true);const payload=await this.syncPayload();const blob=new Blob([payload],{type:'application/json'});if(picker){const handle=await picker;const writable=await handle.createWritable();await writable.write(blob);await writable.close();alert('Encrypted FinMate-vault.json saved to your selected location.')}else{this.download(payload,'FinMate-vault.json','application/json');alert('Encrypted FinMate-vault.json download started. Choose a local folder in your browser download prompt/settings.')}}catch(e){if(e?.name==='AbortError')return;console.error(e);alert(`Could not export FinMate vault: ${e.message||e}`)}},
 async chooseVaultFile(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{const rec=JSON.parse(await file.text());if(!rec?.iv||!rec?.data||!rec?.passwordWrap)throw new Error('This is not a compatible encrypted FinMate-vault.json file.');if(!confirm('Import this encrypted vault? It will replace the data currently open in FinMate on this device. Your existing data is not deleted from other devices or Drive. Continue?'))return;let importedState=null;try{importedState=await this.decrypt(rec,this.cryptoKey);await this.applyImportedVault(importedState,this.cryptoKey,null)}catch(firstErr){this.passwordModal('Enter the master password used to create this FinMate vault.',async pass=>{try{const raw=await this.unwrapKey(rec.passwordWrap,pass);const key=await crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},true,['encrypt','decrypt']);const data=await this.decrypt(rec,key);await this.applyImportedVault(data,key,pass)}catch(err){alert('Could not open this vault. Check the master password and confirm the file is intact.')}})} }catch(e){alert(`Vault import failed: ${e.message||e}`)}};input.click()},
 async applyImportedVault(data,key,pass){this.cryptoKey=key;this.state=data;this.migrate();if(pass)await this.persist(true,null,{dataKey:key,pass});else await this.persist(true);this.render();alert('FinMate vault retrieved from the selected local file.')},
 setDriveProgress(message){let el=document.getElementById('driveSyncProgress');if(!el){document.body.insertAdjacentHTML('beforeend',`<div id="driveSyncProgress" role="status" aria-live="polite" style="position:fixed;z-index:99999;left:50%;bottom:22px;transform:translateX(-50%);width:min(92vw,440px);padding:14px 18px;border-radius:12px;background:var(--panel,#10213e);border:1px solid var(--border,#31435f);box-shadow:0 8px 32px #0005;color:var(--text,#fff);font-weight:600;text-align:center"></div>`);el=document.getElementById('driveSyncProgress')}if(el)el.textContent=message},
 clearDriveProgress(){document.getElementById('driveSyncProgress')?.remove()},
'''
