s=s.replace("const payload=await this.syncPayload();\n    if(id){const r=await fetch", "const payload=await this.syncPayload();if(!silent)this.setDriveProgress(`Uploading encrypted vault · ${(new Blob([payload]).size/1048576).toFixed(2)} MB…`);\n    if(id){const r=await fetch",1)
s=s.replace("await this.persist();if(!silent)alert('FinMate vault synced to Google Drive.');verifyPromise.then", "await this.persist();if(!silent){this.clearDriveProgress();alert('FinMate vault synced to Google Drive.')}verifyPromise.then",1)
s=s.replace("}catch(e){console.error('FinMate Drive sync',e);if(!silent)alert(`Google Drive sync failed:", "}catch(e){console.error('FinMate Drive sync',e);this.clearDriveProgress();if(!silent)alert(`Google Drive sync failed:",1)
s=s.replace("}finally{this.syncBusy=false}\n },", "}finally{this.clearDriveProgress();this.syncBusy=false}\n },",1)
# sync view buttons
old='<div class="actions"><button class="btn primary" data-action="drive-upload">↑ Upload to Drive</button><button class="btn primary" data-action="drive-download">↓ Retrieve from Drive</button></div></div><details class="panel inset">'
